const r2=x=>Math.round(x*100)/100;
const AV=['🦊','🐼','🐸','🐵','🦁','🐯','🐙','🦄','🐧','🐢','🦖','👽','🤖','👻','🐱','🐶','🐰','🐻','🦉','🐳'];
const NM={rich:'Богачи',classic:'Классика',blitz:'Блиц',allin:'Ва-банк',gold:'Золотая лихорадка',surv:'Выживание'};
const SIM=()=>S.mode==='rich'||S.mode==='gold';
const newState=()=>({phase:'lobby',mode:'rich',endType:'time',endValue:3,players:{},order:[],host:null,status:'Ждём игроков…',log:[],turn:0,round:1,adv:0,turnEnds:0,endsAt:0,last:null,final:null,mult:1,boostEnds:0,nextBoost:0});
let S=null,CUR=null;const rooms={},U={},conns=new Set(),MAXP=10,IDLE_MS=60000;let sid=0,uid=0,listDirty=false;
const use=R=>{CUR=R;S=R.S};
const roomConns=()=>[...conns].filter(c=>{const u=U[c.tok];return u&&u.room===CUR.code});
const rnd=n=>Math.floor(Math.random()*n);
const val=p=>r2(Object.entries(p.inv).reduce((a,[i,c])=>a+CAT[i][1]*c,0)+(p.bal||0));
const cnt=p=>Object.values(p.inv).reduce((a,c)=>a+c,0);
const alive=p=>cnt(p)>0||(p.bal||0)>=1;
const logo=m=>{S.log.unshift(m);S.log=S.log.slice(0,40)};
const add=(p,i,n=1)=>{p.inv[i]=(p.inv[i]||0)+n};
const take=(p,i,n=1)=>{p.inv[i]-=n;if(!p.inv[i])delete p.inv[i]};
const say=m=>{S.status=m;S.log.unshift(m);S.log=S.log.slice(0,40)};
const TURN=()=>({surv:30000,blitz:12000,allin:30000}[S.mode]||45000);
const online=pid=>[...conns].some(c=>{const u=U[c.tok];return u&&u.pid===pid});
const nearest=D=>{let b=0;CAT.forEach((c,j)=>{if(Math.abs(Math.log(c[1]/D))<Math.abs(Math.log(CAT[b][1]/D)))b=j});return b};
// выбор цели: tm 'x' множитель, 'p' шанс, 'm' вручную
function pick(sum,tm,tv,man){
  if(tm==='m')return CAT[man]&&CAT[man][1]>sum?man:-1;
  const D=tm==='x'?sum*tv:sum*(1-FEE)/tv;let b=-1,bd=1e9;
  CAT.forEach((c,i)=>{if(c[1]>sum){const d=Math.abs(Math.log(c[1]/D));if(d<bd){bd=d;b=i}}});return b}
function pub(){const P={};
  for(const[id,p]of Object.entries(S.players))P[id]={name:p.name,av:p.av,inv:p.inv,bal:p.bal||0,val:val(p),beg:p.beg,out:p.out,spec:!!p.spec,left:!!p.left,conn:online(id)};
  return{k:'st',code:CUR.code,title:CUR.title,phase:S.phase,mode:S.mode,endType:S.endType,endValue:S.endValue,host:S.host,order:S.order,turn:S.turn,round:S.round,
    turnEnds:S.turnEnds,endsAt:S.endsAt,adv:S.adv?1:0,status:S.status,log:S.log,last:S.last,final:S.final,now:Date.now(),mult:S.mult,boostEnds:S.boostEnds,fee:FEE,players:P}}
function bc(){const m='data: '+JSON.stringify(pub())+'\n\n';for(const c of roomConns()){try{c.res.write(m)}catch(e){}}}
function fin(reason){
  const ids=Object.keys(S.players).filter(i=>!S.players[i].spec&&!S.players[i].left).sort((a,b)=>{const A=S.players[a],B=S.players[b];
    if(S.mode==='surv'){if(A.out!==B.out)return A.out?1:-1;if(A.out&&A.outR!==B.outR)return B.outR-A.outR}
    return val(B)-val(A)});
  S.phase='ended';S.mult=1;S.final=ids;S.adv=0;S.turnEnds=0;listDirty=true;
  if(!ids.length){say('🏁 Игра окончена: все вышли.');return}
  say(`🏁 ${reason} Победитель: ${S.players[ids[0]].av} ${S.players[ids[0]].name}!`)}
function checkEnd(){
  if(S.phase!=='playing')return;
  if(S.endType==='target'){const w=Object.values(S.players).find(p=>!p.spec&&!p.left&&val(p)>=S.endValue);if(w)return fin(`${w.name} набрал ${S.endValue}¢.`)}
  if(S.endsAt&&Date.now()>=S.endsAt)fin('Время вышло.')}
function roundEnd(){
  if(S.mode==='surv'){
    const al=S.order.filter(i=>!S.players[i].out),m=Math.min(...al.map(i=>val(S.players[i])));
    const lo=al.filter(i=>val(S.players[i])===m),v=S.players[lo[rnd(lo.length)]];
    v.out=true;v.outR=S.round;v.beg=false;say(`☠️ ${v.name} вылетает (${m}¢)`);
    if(al.length-1<=1){fin('Остался один.');return true}
  }else if(S.endType==='rounds'&&S.round>=S.endValue){fin('Круги закончились.');return true}
  return false}
function next(){
  const n=S.order.length;
  for(let k=0;k<n;k++){
    S.turn++;
    if(S.turn>=n){S.turn=0;if(roundEnd())return;S.round++}
    const p=S.players[S.order[S.turn]];
    if(!p.out&&alive(p)){S.adv=0;S.turnEnds=Date.now()+TURN();S.status=`Ход: ${p.av} ${p.name}`;return}}
  fin('Все стали бомжами.')}
const unbeg=()=>Object.values(S.players).forEach(p=>{if(p.beg&&alive(p))p.beg=false});

function roomAct(a,u){
  let pid=u.pid;const p=S.players[pid],now=Date.now();
  if(!p)return{err:'Сначала войди'};
  const host=pid===S.host;
  if(a.type==='kick'){
    if(!host||S.phase!=='lobby')return{err:'Только хост'};
    const q=S.players[a.pid];if(!q||a.pid===pid)return{err:'Нельзя'};
    const kt=tokOf(a.pid);if(kt){leaveRoom(U[kt]);pushMe(kt);use(rooms[u.room]||CUR)}else delete S.players[a.pid];
    bc();return{}}
  if(a.type==='set'){
    if(!host||S.phase!=='lobby')return{err:'Только хост'};
    const m=NM[a.mode]?a.mode:S.mode,ok={rich:['time','target'],classic:['time','rounds','target'],blitz:['rounds','time','target'],allin:['rounds','time','target'],gold:['time','target'],surv:['none']}[m];
    let et=ok.includes(a.endType)?a.endType:ok[0],ev=Math.round(+a.endValue)||1;
    const lim={time:[1,60],rounds:[1,100],target:[10,1e6],none:[0,0]}[et];
    listDirty=true;S.mode=m;S.endType=et;S.endValue=Math.min(lim[1],Math.max(lim[0],ev));bc();return{}}
  if(a.type==='start'){
    if(!host||S.phase!=='lobby')return{err:'Только хост'};
    const ids=Object.keys(S.players);if(S.mode==='surv'&&ids.length<2)return{err:'Нужно минимум 2 игрока'};
    ids.forEach(i=>Object.assign(S.players[i],{inv:{0:3},bal:0,beg:false,out:false,busy:0}));
    Object.assign(S,{order:ids.sort(()=>Math.random()-.5),phase:'playing',turn:0,round:1,adv:0,mult:1,boostEnds:0,nextBoost:now+15000,last:null,final:null,log:[],
      endsAt:S.endType==='time'?now+S.endValue*60000:0,turnEnds:SIM()?0:now+TURN()});
    listDirty=true;say(`Старт! Режим «${NM[S.mode]}»`);if(!SIM())S.status=`Ход: ${S.players[S.order[0]].av} ${S.players[S.order[0]].name}`;
    bc();return{}}
  if(a.type==='lobby'){
    if(!host||S.phase!=='ended')return{err:'Нельзя'};
    Object.values(S.players).forEach(q=>Object.assign(q,{inv:{},bal:0,beg:false,out:false,spec:false}));
    Object.keys(S.players).forEach(i=>{if(S.players[i].left)delete S.players[i]});listDirty=true;
    Object.assign(S,{mult:1,phase:'lobby',final:null,last:null,status:'Ждём игроков…'});bc();return{}}
  if(S.phase!=='playing')return{err:'Игра не идёт'};
  if(p.spec)return{err:'Ты наблюдатель 👀 Играть начнёшь со следующей игры'};
  const turnMode=!SIM(),myTurn=S.order[S.turn]===pid;
  if(a.type==='spin'){
    if(S.mode==='allin')a={...a,stake:{...p.inv}};
    if(p.out)return{err:'Ты вылетел'};
    if(turnMode&&!myTurn)return{err:'Не твой ход'};
    if(S.adv||now<(p.busy||0))return{err:'Подожди'};
    let sum=0;const stake={};
    for(const[i,c]of Object.entries(a.stake||{})){const n=Math.floor(c);if(!CAT[i]||n<1||n>(p.inv[i]||0))return{err:'Нет такого скина'};stake[i]=n;sum=r2(sum+CAT[i][1]*n)}
    if(!sum)return{err:'Выбери скины'};
    const tv=+a.tv;if((a.tm!=='m'&&!(tv>0))||(a.tm==='p'&&tv>=1))return{err:'Ошибка'};
    const t=pick(sum,a.tm,tv,a.man);if(t<0)return{err:'Нет цели дороже ставки'};
    const chance=Math.min(.98,(a.tm==='p'?tv:sum*(1-FEE)/CAT[t][1])*S.mult);
    for(const i in stake)take(p,i,stake[i]);
    const roll=Math.random(),win=roll<chance;if(win)add(p,t);
    S.last={id:++sid,by:pid,stake,sum,t,chance,roll,win};
    const st=Object.entries(stake).map(([i,n])=>CAT[i][0]+(n>1?'×'+n:'')).join('');
    say(`${p.name}: ${st} → ${CAT[t][0]} (${(chance*100).toFixed(1)}%) — ${win?'ПОБЕДА 🎉':'сгорело 🔥'}`);
    if(turnMode){S.adv=now+ANIM;S.turnEnds=0}else p.busy=now+ANIM;
    unbeg();checkEnd();bc();return{}}
  if(a.type==='sell'){
    if(S.mode==='allin')return{err:'В Ва-банке магазин закрыт'};
    if(p.out)return{err:'Ты вылетел'};
    let sum=0;const stake={};
    for(const[i,c]of Object.entries(a.stake||{})){const n=Math.floor(c);if(!CAT[i]||n<1||n>(p.inv[i]||0))return{err:'Нет такого скина'};stake[i]=n;sum=r2(sum+CAT[i][1]*n)}
    if(!sum)return{err:'Выбери скины для продажи'};
    for(const i in stake)take(p,i,stake[i]);
    p.bal=r2((p.bal||0)+sum);logo(`💱 ${p.name} продал скины за ${sum}¢`);unbeg();checkEnd();bc();return{}}
  if(a.type==='buy'){
    if(S.mode==='allin')return{err:'В Ва-банке магазин закрыт'};
    const i=a.idx,q=Math.floor(a.qty);
    if(p.out||!CAT[i]||!(q>=1&&q<=100))return{err:'Нельзя'};
    const cost=r2(CAT[i][1]*q);if(cost>(p.bal||0))return{err:'Не хватает баланса'};
    p.bal=r2(p.bal-cost);add(p,i,q);logo(`🛒 ${p.name} купил ${CAT[i][0]}×${q}`);unbeg();checkEnd();bc();return{}}
  if(a.type==='skip'){
    if(!turnMode||!myTurn||S.adv)return{err:'Нельзя'};
    say(`${p.name} пропускает ход`);next();bc();return{}}
  if(a.type==='free'){
    if(!SIM())return{err:'Нельзя'};
    if(now<(p.fr||0))return{};p.fr=now+300;add(p,0);checkEnd();bc();return{}}
  if(a.type==='beg'){
    if(!turnMode||p.out||alive(p))return{err:'Нельзя'};
    p.beg=true;say(`🥺 ${p.name} просит кормешку!`);bc();return{}}
  if(a.type==='feed'){
    const q=S.players[a.to],i=a.idx;
    if(!turnMode||!q||!q.beg||q.out||a.to===pid||!(p.inv[i]>0))return{err:'Нельзя'};
    take(p,i);add(q,i);q.beg=false;let m=`🍽 ${p.name} накормил ${q.name}: ${CAT[i][0]}`;
    if(Math.random()<.25){const b=nearest(CAT[i][1]*2);add(p,b);m+=` и получил награду ${CAT[b][0]}!`}
    say(m);unbeg();checkEnd();bc();return{}}
  return{err:'Неизвестно'}}

const tokOf=pid=>Object.keys(U).find(t=>U[t].pid===pid&&U[t].room);
function listPub(){return Object.values(rooms).filter(R=>!R.priv).sort((a,b)=>b.created-a.created).map(R=>{
  const es=Object.entries(R.S.players),h=R.S.players[R.S.host];
  return{code:R.code,title:R.title,host:h?h.name:'—',n:es.filter(([,p])=>!p.spec&&!p.left).length,max:MAXP,sp:es.filter(([,p])=>p.spec).length,phase:R.S.phase,mode:NM[R.S.mode]}})}
function bcList(){const m='data: '+JSON.stringify({k:'list',rooms:listPub()})+'\n\n';for(const c of conns){const u=U[c.tok];if(!u||!u.room){try{c.res.write(m)}catch(e){}}}}
function pushMe(tok){const u=U[tok];if(!u)return;
  const m='data: '+JSON.stringify({k:'me',me:u.pid||null,room:u.room||null,name:u.name,note:(()=>{const n=u.note||null;u.note=null;return n})()})+'\n\n';
  for(const c of conns)if(c.tok===tok){try{c.res.write(m);
    if(u.room&&rooms[u.room]){use(rooms[u.room]);c.res.write('data: '+JSON.stringify(pub())+'\n\n')}
    else c.res.write('data: '+JSON.stringify({k:'list',rooms:listPub()})+'\n\n')}catch(e){}}}
function mkCode(){let c;do{c=Array.from({length:4},()=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[rnd(32)]).join('')}while(rooms[c]);return c}
function leaveRoom(u){
  const R=rooms[u.room],pid=u.pid;u.room=null;u.pid=null;if(!R)return;
  use(R);const p=S.players[pid];if(!p)return;
  if(S.phase==='lobby'||p.spec||p.left){delete S.players[pid];if(S.phase==='lobby')say(`🚪 ${p.name} вышел`);else logo(`👀 ${p.name} ушёл`)}
  else{
    p.out=true;p.beg=false;p.left=true;p.outR=S.round;logo(`🚪 ${p.name} вышел из игры`);
    if(S.phase==='playing'){
      const rest=S.order.filter(i=>!S.players[i].out);
      if(rest.length===0||(S.mode==='surv'&&rest.length<=1))fin(rest.length?'Остался один.':'Все вышли.');
      else if(!SIM()&&S.order[S.turn]===pid&&!S.adv)next()}}
  if(S.host===pid){const ids=Object.keys(S.players);S.host=ids.find(i=>!S.players[i].left&&!S.players[i].spec&&online(i))||ids.find(i=>!S.players[i].left)||null}
  if(!Object.values(S.players).some(q=>!q.left))delete rooms[R.code];else bc();
  listDirty=true}
function act(a){
  const tok=a.t;if(typeof tok!=='string'||tok.length<8)return{err:'Ошибка'};
  const u=U[tok]||(U[tok]={name:'',room:null,pid:null,av:null,input:Date.now()});
  if(a.type==='alive'){u.input=Date.now()-Math.max(0,Math.min(+a.idle||0,3600000));return{ok:1}}
  u.input=Date.now();
  if(a.type==='nick'){
    if(u.room)return{err:'Сначала выйди из лобби'};
    const name=String(a.name||'').trim().slice(0,12);if(!name)return{err:'Введи ник'};
    u.name=name;u.av=u.av||AV[rnd(AV.length)];pushMe(tok);return{ok:1}}
  if(!u.name)return{err:'Сначала введи ник'};
  if(a.type==='leave'){if(u.room)leaveRoom(u);pushMe(tok);return{ok:1}}
  if(a.type==='create'||a.type==='enter'){
    if(u.room&&rooms[u.room]){if(a.type==='enter'&&String(a.code||'').trim().toUpperCase()===u.room)return{me:u.pid,room:u.room};return{err:'Сначала выйди из текущего лобби'}}
    u.room=null;u.pid=null;let R;
    if(a.type==='create'){
      if(Object.keys(rooms).length>=60)return{err:'Слишком много лобби, попробуй позже'};
      R={code:mkCode(),title:String(a.title||'').trim().slice(0,24)||('Лобби '+u.name),priv:!!a.priv,created:Date.now(),idle:0,S:newState()};rooms[R.code]=R;
    }else{R=rooms[String(a.code||'').trim().toUpperCase()];if(!R)return{err:'Лобби не найдено. Проверь код'}}
    use(R);const ps=Object.values(S.players).filter(q=>!q.left);
    const fail=e=>{if(a.type==='create')delete rooms[R.code];return{err:e}};
    if(S.phase==='lobby'&&ps.filter(q=>!q.spec).length>=MAXP)return fail('Лобби заполнено');
    if(ps.some(q=>q.name.toLowerCase()===u.name.toLowerCase()))return fail('В лобби уже есть игрок с таким ником. Смени ник');
    const pid='p'+(++uid),used=ps.map(q=>q.av),fr=AV.filter(x=>!used.includes(x)),pool=fr.length?fr:AV;
    S.players[pid]={name:u.name,av:fr.includes(u.av)?u.av:pool[rnd(pool.length)],inv:{},beg:false,out:false,spec:S.phase!=='lobby'};
    if(!S.host||!S.players[S.host])S.host=pid;
    u.room=R.code;u.pid=pid;
    if(S.phase==='lobby')say(`${u.name} зашёл в лобби`);else logo(`👀 ${u.name} наблюдает за игрой`);
    bc();listDirty=true;pushMe(tok);return{me:pid,room:R.code}}
  const R=u.room&&rooms[u.room];
  if(!R){u.room=null;u.pid=null;pushMe(tok);return{err:'Ты не в лобби'}}
  use(R);return roomAct(a,u)}

function tickRoom(now){
  if(!S.players[S.host]||!online(S.host)){const on=Object.keys(S.players).find(id=>online(id)&&!S.players[id].left);if(on&&on!==S.host){S.host=on;bc();listDirty=true}}
  if(S.phase==='lobby'){for(const id of Object.keys(S.players)){const q=S.players[id];
    if(online(id))q.off=0;else{q.off=q.off||now;if(now-q.off>90000){const t=tokOf(id);if(t){leaveRoom(U[t]);pushMe(t)}else delete S.players[id];return}}}}
  if(S.phase!=='playing')return;
  if(!SIM()){
    if(S.adv&&now>=S.adv){next();bc()}
    else if(!S.adv){const cur=S.order[S.turn];
      if(now>S.turnEnds||!online(cur)){say(`${S.players[cur].name} пропускает ход`);next();bc()}}}
  if(S.mode==='gold'){
    if(S.mult>1&&now>=S.boostEnds){S.mult=1;S.nextBoost=now+20000+rnd(15000);logo('Лихорадка закончилась');bc()}
    else if(S.mult===1&&now>=S.nextBoost){S.mult=1.5;S.boostEnds=now+12000;say('🔥 ЗОЛОТАЯ ЛИХОРАДКА! Шансы ×1.5 на 12 секунд');bc()}}
  const ph=S.phase;checkEnd();if(S.phase!==ph){bc();listDirty=true}}
setInterval(()=>{const now=Date.now();for(const R of Object.values(rooms)){use(R);tickRoom(now)}if(listDirty){listDirty=false;bcList()}},500);
setInterval(()=>{const now=Date.now();for(const R of Object.values(rooms)){use(R);
  if(Object.keys(S.players).some(id=>online(id)))R.idle=0;else{R.idle=R.idle||now;if(now-R.idle>600000){delete rooms[R.code];for(const u of Object.values(U))if(u.room===R.code){u.room=null;u.pid=null}listDirty=true}}}},30000);
setInterval(()=>{const now=Date.now();for(const tok of Object.keys(U)){const u=U[tok];if(u.room&&now-(u.input||now)>IDLE_MS){u.note='idle';leaveRoom(u);pushMe(tok)}}},2000);
setInterval(()=>conns.forEach(c=>{try{c.res.write(': ping\n\n')}catch(e){}}),15000);

http.createServer((req,res)=>{
  const u=new URL(req.url,'http://x');
  if(u.pathname==='/events'){
    const t=u.searchParams.get('t')||'';
    res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-cache','Connection':'keep-alive','X-Accel-Buffering':'no'});
    const c={res,tok:t};conns.add(c);res.write('retry: 1000\n\n');
    const us=U[t];
    res.write('data: '+JSON.stringify({k:'me',me:us&&us.pid||null,room:us&&us.room||null,name:us?us.name:'',cat:CAT})+'\n\n');
    if(us&&us.room&&rooms[us.room]){use(rooms[us.room]);bc()}else res.write('data: '+JSON.stringify({k:'list',rooms:listPub()})+'\n\n');
    req.on('close',()=>{conns.delete(c);const u2=U[t];if(u2&&u2.room&&rooms[u2.room]){use(rooms[u2.room]);bc()}});return}
  if(req.method==='POST'&&u.pathname==='/act'){
    let b='';req.on('data',d=>b+=d);
    req.on('end',()=>{let r;try{r=act(JSON.parse(b))}catch(e){r={err:'Ошибка'}}
      res.writeHead(200,{'Content-Type':'application/json'});res.end(JSON.stringify(r))});return}
  res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});res.end(HTML)
}).listen(PORT,'0.0.0.0',()=>{
  console.log('\n🎰 Рулет Андрея запущен! (версия 17) Пусть друзья откроют в браузере:');
  try{for(const l of Object.values(os.networkInterfaces()))for(const i of l)
    if(i.family==='IPv4'&&!i.internal)console.log('   http://'+i.address+':'+PORT)}catch(e){}
  console.log('   Если адрес не показался: у раздающего телефона обычно http://192.168.43.1:'+PORT);
  console.log('   Сам хост открывает: http://localhost:'+PORT);
  console.log('')});
